import React from "react";
import Card from "./Card";

const Cards = ({courses}) => {
  let allCourses = [];

  

  // returns you a list of all course received from the api response 
  const getCourses = () => {
    let allCourses = [];
    
    Object.values(courses).forEach((courseCategory) => {
       courseCategory.forEach((course) => {
            allCourses.push(course);
       });

    });
    return allCourses;
  }

 return (
    <div>
      {getCourses().map((course) => (
        <Card
          key={course.id}
          course={course}
        />
      ))}
    </div>
  );
};

export default Cards;
